return {
  [ [[v5748eaic9r83]] ] = { t = [[灵性咒法与狂野奥术]], q = [[为什么道途能力「灵性咒法」和「狂野奥术」的规则文字略有不同？]], a = [[这两项能力本应运作方式相同，规则文字也应完全一致（只是一个作用于神术，一个作用于奥术）。此外，两者可以施展哪些法术，还需要进一步澄清。

在《神话冒险》官方勘误发布之前，这两项能力的建议文字如下：

'''灵性咒法（Su）'''：以一个标准动作，你能消耗一次神话之力使用次数，来施展任意一个神术而不需消耗已准备的法术或法术位。该法术必须在你某个神术施法职业的法术列表中（或者你的领域或秘示域法术列表中），其环位不得超过你能以该神术施法职业施展的最高环位，且施法时间必须是“1个标准动作”（或更短）。你无需准备此法术，它也无需在你的已知法术列表中。以此方式施法时，在判断任何依赖等级的效应时，你的施法者等级视为提升2级。你能将已知的超魔专长应用于此法术，但调整后的总环位不得超过你从该施法职业所能施展的最高神术环位。

'''狂野奥术（Su）'''：以一个标准动作，你能消耗一次神话之力使用次数，来施展任意一个奥术而不需消耗已准备的法术或法术位。该法术必须在你某个奥术施法职业的法术列表中，其环位不得超过你能以该奥术施法职业施展的最高环位，且施法时间必须是“1个标准动作”（或更短）。你无需准备此法术，它也无需在你的已知法术列表中。以此方式施法时，在判断任何依赖等级的效应时，你的施法者等级视为提升2级。你能将已知的超魔专长应用于此法术，但调整后的总环位不得超过你从该施法职业所能施展的最高奥术环位。]], book = [[神话冒险]], date = [[2013/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1gl#v5748eaic9r83]], cat = [[FAQ]], ai = true, pages = { [[圣者]], [[大法师]] } },
  [ [[v5748eaic9r5f]] ] = { t = [[DR/传奇与可变增强加值]], q = [[《神话冒险》（第7页）克服 DR/传奇的新规则，与破敌、暴怒这类增强加值可变的武器特殊能力如何配合？]], a = [=[现在，用魔法武器克服 DR/传奇其实有两种方式。

第一种见于《怪物图鉴》的通用怪物规则：你可以使用实际增强加值为+6或更高的武器。目前《开拓者》RPG 里没有永久增强加值达到+6或更高的武器（不过某些魔法或职业能力可以让你暂时获得+6或更高的增强加值）。

第二种见于《神话冒险》：你可以使用总“加值等效”为+6或更高的武器。例如，一把+1[[斩首]]长剑，和一把+2[[炽焰]][[冻寒]][[电击]][[锐锋]]长剑，都是+6等效的魔法武器。

具有有条件或可变增强加值的武器（如[[破敌]]或[[暴怒(武器附魔)|暴怒]]）则两种方式兼得：以基础值计，它包含增强加值与特殊能力的加值等效；当有条件或可变的增强加值生效时，这些加值也会加进总数。

例如，一把+3破敌（不死生物）长剑是+4等效的武器，单靠这个还不足以克服 DR/传奇。对不死生物使用时，它的增强加值额外提高+2，实际上就成了+6等效的武器（+3基础增强加值，破敌带来+1等效，对抗不死生物时破敌带来+2有条件增强加值），因此能克服该不死生物的 DR/传奇。（另一种看法是：破敌生效时，把它的有条件+2增强加值加到武器通常的+4等效加值上，暂时得到一把+6等效的武器。）]=], book = [[神话冒险]], date = [[2013/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1gl#v5748eaic9r5f]], cat = [[FAQ]], ai = true, pages = { [[伤害减免]], [[魔法物品/武器]] } },
  [ [[v5748eaic9vol]] ] = { t = [[神话巨龙形态]], q = [=[神话巨龙形态说它把我的喷吐武器伤害提高到10d6，但对于[[巨龙形态 II]]或[[巨龙形态 III]]来说，10d6其实并不是提高。这是不是说神话版本反而会降低我的伤害？]=], a = [[不会。神话巨龙形态应当是让你的喷吐武器伤害增加2d8。这将在下一次勘误中体现。]], book = [[神话冒险]], date = [[2017/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1gl#v5748eaic9vol]], cat = [[FAQ]], ai = true, pages = { [[巨龙形态 (神话)]] } },
  [ [[v5748eaic9r5o]] ] = { t = [[神话怪物]], q = [[有神话怪物吗？]], a = [=[有。《神话冒险》收录了40头常见怪物（犬魔、恶魔、龙、巨人、枭熊等等）的神话强化版，让它们能向神话PC发起挑战。本书还提供了几个新的神话模板，可以快速给怪物加上神话能力，另有定制新神话怪物的规则，以及适用于神话生物的新[[通用怪物规则]]。

《[[怪物图鉴4]]》（2013年末发售）收录了更多神话怪物。]=], book = [[神话冒险]], date = [[2013/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1gl#v5748eaic9r5o]], cat = [[FAQ]], ai = true, pages = { [[神话怪物]] } },
  [ [[v5748eaic9r5n]] ] = { t = [[神话规则如何运作]], q = [[神话规则是怎么运作的？]], a = [=[你的神话角色要选择一条神话道途，它会给予一些通用能力。例如，你获得每天数次动用神话之力的能力，可以在掷出d20之后改动结果。神话角色也更耐打，会获得额外的生命值。

你一开始是1阶神话角色。神话阶层不是靠积累经验值获得的，而是要完成战役特有的目标（由GM决定）才能晋入下一阶。这套体系下，你的神话阶层与角色等级无关。你依然照常获得经验值、照常升级，但偶尔你的神话阶层也会提升，为你的角色添上一些新的神话能力和力量。

神话阶层共有10阶。到了第10阶，你的角色几近不可阻挡，力量近乎半神（实际上，你可以选择的一项神话能力就是把法术授予你的追随者）。

要注意的是，神话规则固然为游戏增添内容，却不一定会让游戏更复杂。一项新的神话能力也许能让你自动通过一次检定、无视一次[[借机攻击]]，或者绕过某条拖慢游戏进度的规则。神话并不是给你的角色添加更多数学运算，而是让你的角色能做出普通规则下做不到的惊人英雄壮举。]=], book = [[神话冒险]], date = [[2013/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1gl#v5748eaic9r5n]], cat = [[FAQ]], ai = true, pages = { [[神话规则]] } },
  [ [[v5748eaic9raz]] ] = { t = [[神话吸血鬼：克服弱点]], q = [[神话吸血鬼的“克服弱点”能力，比标准吸血鬼的弱点好在哪里？]], a = [=[神话吸血鬼在阳光直射下应当只是[[恶心]]，而不是[[反胃]]。

另外，与标准吸血鬼不同，神话吸血鬼在暴露于阳光直射的第二轮时不应被彻底摧毁（它每轮会遭受10点伤害、失去快速治疗并陷入恶心，但除此之外仍可行动，只要还有生命值就能存活）。

这将在《神话冒险》的下一次印刷中更正。]=], book = [[神话冒险]], date = [[2013/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1gl#v5748eaic9raz]], cat = [[FAQ]], ai = true, pages = { [[神话吸血鬼]] } },
  [ [[v5748eaic9r5l]] ] = { t = [[什么是神话]], q = [[什么是神话？]], a = [[神话规则提供了一种玩《开拓者》的新方式。它沿用你熟悉的所有规则，但为游戏添加了新的一层。神话冒险者地位凌驾于非神话的同行之上，获得他们无法企及的力量与能力，因而能迎战更强的敌人、面对更艰巨的挑战。神话角色会对上神祇的代理人，一头冲进深渊，致力于铸就传奇，同时面对各式各样的敌人，从普通怪物到其他神话角色。如果艾尔里克、法夫赫德、灰鼠、赫拉克勒斯或亚瑟王是在《开拓者》中创造的，他们就会是神话角色。]], book = [[神话冒险]], date = [[2013/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1gl#v5748eaic9r5l]], cat = [[FAQ]], ai = true, pages = { [[神话规则]] } },
  [ [[v5748eaic9r5m]] ] = { t = [[神话与史诗规则]], q = [[神话是史诗规则的替代品吗？]], a = [[不是。“史诗”规则通常指“适用于20级以上角色的规则”。与史诗规则不同，神话规则用在1级角色身上和用在20级角色身上同样容易。当你的PC达到20级后，你甚至可以用神话规则让他们继续变强，去对付游戏里最强悍的对手，从远古巨龙到恶魔领主。与此同时，低等级的神话角色可以去对付你已经熟悉的怪物，而在这个等级上，非神话角色面对它们必死无疑。]], book = [[神话冒险]], date = [[2013/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1gl#v5748eaic9r5m]], cat = [[FAQ]], ai = true, pages = { [[神话规则]] } },
